mapper.select:
select id, client_id, classify_result from asset_classify_client where id in ( select max(c.id) from asset_classify a inner join asset_classify_client c on a.id = c.asset_classify_id where a.finish = 1
and c.client_id in
#{item}
and a.id in (select max(asset_classify_id) from asset_classify_client c inner join asset_classify a on a.id = c.asset_classify_id group by c.client_id) group by client_id);

select a.id, a.client_id, a.classify_result from asset_classify_client a inner join ( select acc.client_id, max(acc.asset_classify_id) as asset_classify_id from asset_classify_client acc right join asset_classify ac on acc.asset_classify_id = ac.id where ac.finish = 1 group by acc.client_id ) last on a.client_id = last.client_id and a.asset_classify_id = last.asset_classify_id where a.classify_result = #{classifyResult}
and a.client_id in
#{item}
